CREATE TABLE send_permissions(credential_id TEXT NOT NULL REFERENCES credentials(id) ON DELETE CASCADE,credential_revision INTEGER NOT NULL,chat_id TEXT NOT NULL REFERENCES chats(id) ON DELETE CASCADE,PRIMARY KEY(credential_id,chat_id));
CREATE TABLE send_requests(credential_id TEXT NOT NULL REFERENCES credentials(id) ON DELETE CASCADE,request_id TEXT NOT NULL,account TEXT NOT NULL,chat_id TEXT NOT NULL,digest BLOB NOT NULL CHECK(length(digest)=32),protocol_id TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('outcome_unknown','accepted','failed')),accepted_at INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(credential_id,request_id));
